  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-contrast: #ffffff;
  --danger: #b42318;
  --danger-bg: #fef3f2;
  --focus: #1d4ed8;
  --radius: 12px;
  --shadow: 0 10px 30px rgba(15, 23, 42, 0.08);
