  // Wait for React to render
  await page.waitForSelector('#agree-terms', { timeout: 10000 });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const result = await page.evaluate(async () => await window.axe.run());
  await browser.close();
  const wcag = result.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = result.violations.filter(v => v.tags.includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, help: v.help, targets: v.nodes.map(n => n.target) }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();

